require'bots.FretBots.Debug'require'bots.FretBots.DataTables'require'bots.FretBots.Settings'require'bots.FretBots.modifiers.modifier_seasonal_party_hat'if Modifier==nil then Modifier={}end;function Modifier:ApplyGlobalModifier(a)if a and a:IsAlive()and not a:HasModifier("modifier_seasonal_party_hat")and a.stats then a:AddNewModifier(a,nil,"modifier_seasonal_party_hat",{})Debug:Print('Added modifier to:'..a.stats.name)end end;function Modifier:ApplySpecialModifiers(a)if a and a:IsAlive()and a.stats then if not a:HasModifier("modifier_special_bonus_cooldown_reduction")then a:AddNewModifier(a,nil,"modifier_special_bonus_cooldown_reduction",{})Debug:Print('Added modifier_special_bonus_cooldown_reduction to:'..a.stats.name)end;if not a:HasModifier("modifier_special_bonus_respawn_reduction")then a:AddNewModifier(a,nil,"modifier_special_bonus_respawn_reduction",{})Debug:Print('Added modifier_special_bonus_respawn_reduction to:'..a.stats.name)end end end;function Modifier:ApplyHighFiveModifier(a)if a and a:IsAlive()and a.stats then if not a:HasModifier("modifier_plus_high_five_requested")then a:AddNewModifier(a,nil,"modifier_plus_high_five_requested",{})Debug:Print('Added modifier_plus_high_five_requested to:'..a.stats.name)end end end;function Modifier:RemoveHighFiveModifier(a)if a and a.stats then if a:HasModifier("modifier_plus_high_five_requested")then a:RemoveModifierByName("modifier_plus_high_five_requested")end;if a:HasModifier("modifier_taunt")then a:RemoveModifierByName("modifier_taunt")end end end;function Modifier:Initialize()for b=2,3 do for c,a in pairs(AllBots[b])do if a~=nil and a.stats~=nil then Modifier:ApplySpecialModifiers(a)end end end;Debug:Print('Registering modifier event for bots.')ListenToGameEvent("npc_spawned",Dynamic_Wrap(Modifier,'OnNPCSpawned'),Modifier)end;function Modifier:OnNPCSpawned(d)local e=EntIndexToHScript(d.entindex)Modifier:ApplySpecialModifiers(e)end